/* From Uiverse.io by myshy13  - Tags: checkbox */
.__UIV_SCOPE__ .container input {
  opacity: 0;
  cursor: pointer;
  display: none;
}

.__UIV_SCOPE__ .container {
  display: block;
  position: relative;
  cursor: pointer;
  font-size: 20px;
  user-select: none;
}

.__UIV_SCOPE__ .checkmark {
  transition: 0.5s ease;
  border-radius: 0.2em;
}

.__UIV_SCOPE__ .checkmark {
  position: relative;
  top: 0;
  left: 0;
  height: 1.3em;
  width: 1.3em;
  background-color: #ccc;
}
.__UIV_SCOPE__ .container input:checked ~ .checkmark {
  background-color: #b30000;
  box-shadow: #ff2929 0px 0px 1em;
  outline: rgb(139, 0, 0) 3px solid;
}

.__UIV_SCOPE__ .checkmark:after {
  content: "";
  position: absolute;
  display: none;
}

.__UIV_SCOPE__ .container input:checked ~ .checkmark::after {
  display: block;
}

.__UIV_SCOPE__ .container .checkmark::after {
  left: 0.45em;
  top: 0.25em;
  width: 0.25em;
  height: 0.5em;
  border: solid white;
  border-width: 0 0.15em 0.15em 0;
  transform: rotate(45deg);
}
